do $test$
declare n numeric; row_value public.alliance_members%rowtype; j jsonb; definition text;
begin
 n := public.qualification_cap_amount('alliance','qualification-test-helper','spend',8000,'a'); if n<>8000 then raise exception 'first credit %',n; end if;
 n := public.qualification_cap_amount('alliance','qualification-test-helper','spend',5000,'b'); if n<>2000 then raise exception 'partial credit %',n; end if;
 n := public.qualification_cap_amount('alliance','qualification-test-helper','spend',5000,'b'); if n<>2000 then raise exception 'retry credit %',n; end if;
 n := public.qualification_cap_amount('alliance','qualification-test-helper','topup',15000,'c'); if n<>10000 then raise exception 'independent topup %',n; end if;
 n := public.qualification_cap_amount('alliance','qualification-test-helper','topup',500,'d'); if n<>0 then raise exception 'zero credit %',n; end if;
 row_value := public.alliance_apply_activity('qualification-test-member','1206138511535898654','spend',8000,'qualification-test-spend-1',null);
 row_value := public.alliance_apply_activity('qualification-test-member','1501098191813214312','spend',5000,'qualification-test-spend-2',null);
 if row_value.qualifying_spend<>10000 then raise exception 'alliance shared daily limit %',row_value.qualifying_spend; end if;
 row_value := public.alliance_apply_activity('qualification-test-member','1501098191813214312','topup',15000,'jkopay-topup:qualification-test-platform:qualification-test-member',null);
 row_value := public.alliance_apply_activity('qualification-test-member','1501098191813214312','topup',500,'qualification-test-topup-2',null);
 if row_value.qualifying_topup<>10000 then raise exception 'alliance topup %',row_value.qualifying_topup; end if;
 row_value := public.alliance_apply_activity('qualification-test-member','1501098191813214312','topup',-15000,'jkopay-refund:qualification-test-platform:qualification-test-member',null);
 if row_value.qualifying_topup<>0 then raise exception 'refund reverses only credited qualification %',row_value.qualifying_topup; end if;
 row_value := public.alliance_apply_activity('qualification-test-member','1501098191813214312','topup',500,'qualification-test-topup-after-refund',null);
 if row_value.qualifying_topup<>0 then raise exception 'refund must not reopen allowance %',row_value.qualifying_topup; end if;
 row_value := public.alliance_apply_activity('qualification-test-member','1206138511535898654','spend',8000,'qualification-test-spend-1',null);
 if row_value.qualifying_spend<>10000 then raise exception 'alliance dedupe'; end if;
 j := public.qiunai_apply_vip_effect('qualification-test-effect1','qualification-test-qiunai','1206138511535898654','spend',8000);
 j := public.qiunai_apply_vip_effect('qualification-test-effect2','qualification-test-qiunai','1206138511535898654','spend',5000);
 if (j->>'total_spent')::numeric<>10000 then raise exception 'qiunai spend %',j; end if;
 j := public.qiunai_apply_vip_effect('qualification-test-effect3','qualification-test-qiunai','1206138511535898654','topup',15000);
 if (j->>'total_topup')::numeric<>10000 then raise exception 'qiunai topup %',j; end if;
 j := public.deepnight_apply_vip_activity_once('qualification-test-effect1','qualification-test-deepnight','1501098191813214312','spend',8000);
 j := public.deepnight_apply_vip_activity_once('qualification-test-effect2','qualification-test-deepnight','1501098191813214312','spend',5000);
 if (j->>'total_spent')::numeric<>10000 then raise exception 'deepnight spend %',j; end if;
 j := public.deepnight_apply_vip_activity_once('qualification-test-effect3','qualification-test-deepnight','1501098191813214312','topup',15000);
 if (j->>'total_topup')::numeric<>10000 then raise exception 'deepnight topup %',j; end if;
 if (j->>'highest_single_topup')::numeric<>15000 then raise exception 'single topup must retain real amount %',j; end if;
 j := public.deepnight_apply_vip_activity_once('qualification-test-effect3','qualification-test-deepnight','1501098191813214312','topup',15000);
 if not (j->>'already_processed')::boolean then raise exception 'deepnight retry'; end if;
 j := public.apply_temporary_legacy_vip_credit('qualification-test-legacy','1206138511535898654','spend',12000);
 if (j->>'total_spent')::numeric<>10000 then raise exception 'legacy spend %',j; end if;
 definition := pg_get_functiondef('public.qualification_cap_amount(text,text,text,numeric,text)'::regprocedure);
 execute replace(definition, 'day_value date := (now() at time zone ''Asia/Taipei'')::date;',
   'day_value date := ''2026-10-05''::date;');
 n := public.qualification_cap_amount('alliance','qualification-test-helper','spend',9000,'next-day');
 if n<>9000 then raise exception 'new day resets allowance %',n; end if;
 execute definition;
 update public.qualification_cap_policy set ends_at=now() where id='2026-10-10';
 n := public.qualification_cap_amount('alliance','qualification-test-expired','spend',15000,'expired');
 if n<>15000 then raise exception 'expiry %',n; end if;
 if ('2026-10-09 16:00:00+00'::timestamptz at time zone 'Asia/Taipei')::timestamp <> '2026-10-10 00:00:00'::timestamp then raise exception 'timezone boundary'; end if;
end;
$test$;
select 'PASS: independent limits, partial/zero credits, retries, two brands, legacy VIP, expiry; all test data rolled back' as verification;
rollback;
